        state.s = (((((state.z + LOG1PQ_S5) * state.z + LOG1PQ_S4) * state.z + LOG1PQ_S3) * state.z + LOG1PQ_S2) * state.z + LOG1PQ_S1) * state.z
            + LOG1PQ_S0;
