type Quad is bytes16;

using {Casting.unwrap} for Quad global;

using {Math.exp2, Math.exp, Math.log, Math.sqrt, Math.max} for Quad global;

using {
    Helpers.add,
    Helpers.sub,
    Helpers.mul,
    Helpers.div,
    Helpers.eq,
    Helpers.neq,
    Helpers.neg,
    Helpers.lt,
    Helpers.lte,
    Helpers.gt,
    Helpers.gte,
    Helpers.abs,
    Helpers.isNaN
} for Quad global;

using {
    Helpers.add as +,
    Helpers.sub as -,
    Helpers.mul as *,
    Helpers.div as /,
    Helpers.eq as ==,
    Helpers.neq as !=,
    Helpers.neg as -,
    Helpers.lt as <,
    Helpers.lte as <=,
    Helpers.gt as >,
    Helpers.gte as >=
} for Quad global;

